begin;
select no_plan();
insert into organizations(id,name) values ('39940000-0000-0000-0000-000000000001','Lookup A'),('39940000-0000-0000-0000-000000000002','Lookup B');
insert into auth.users(id,email) values ('39940000-0000-0000-0000-000000000011','lookup@example.invalid');
insert into profiles(id,org_id,full_name,email,role) values ('39940000-0000-0000-0000-000000000011','39940000-0000-0000-0000-000000000001','Admin','lookup@example.invalid','Admin');
insert into procurements(org_id,title,status,requested_by_id,import_key)
select '39940000-0000-0000-0000-000000000001','Case '||n,'Draft','39940000-0000-0000-0000-000000000011',case when n%2=0 then ' ALPHA ' else 'alpha' end from generate_series(1,205) n;
insert into procurements(org_id,title,status,import_key) values ('39940000-0000-0000-0000-000000000002','Foreign','Draft','alpha');
insert into procurements(id,org_id,title,status,requested_by_id,import_key) values ('39940000-0000-0000-0000-000000000021','39940000-0000-0000-0000-000000000001','Renamed','Draft','39940000-0000-0000-0000-000000000011','original');
update procurements set import_key='  Changed  ' where id='39940000-0000-0000-0000-000000000021';
set local role authenticated;
set local request.jwt.claims = '{"sub":"39940000-0000-0000-0000-000000000011","role":"authenticated"}';
create temporary table page1 as select * from public.lookup_procurement_import_cases(array['alpha',' ALPHA '],p_limit=>999);
select is((select count(*) from page1),200::bigint,'lookup clamps page to 200 and deduplicates input');
select is((select count(*) from public.lookup_procurement_import_cases(array['alpha'],p_limit=>0)),1::bigint,'lookup clamps page to at least one');
create temporary table page2 as select * from public.lookup_procurement_import_cases(array['alpha'],(select normalized_ref from page1 order by normalized_ref desc,id desc limit 1),(select id from page1 order by normalized_ref desc,id desc limit 1),200);
select is((select count(*) from page2),5::bigint,'cursor returns remaining rows');
select is((select count(*) from (select id from page1 union select id from page2) q),205::bigint,'pagination visits each scoped match exactly once');
select is((select count(*) from public.lookup_procurement_import_cases(array['missing'])),0::bigint,'unmatched lookup is empty');
select is((select count(*) from public.lookup_procurement_import_cases(array['changed'])),1::bigint,'lookup tracks changes to the source reference');
select is((select count(*) from public.lookup_procurement_import_cases(array_fill('missing'::text,array[200]))),0::bigint,'lookup accepts 200 references');
select throws_ok($$select * from public.lookup_procurement_import_cases(array_fill('missing'::text,array[201]))$$,'22023',null,'lookup rejects more than 200 references');
select throws_ok($$select * from public.lookup_procurement_import_cases(array['alpha'],p_org_id=>'39940000-0000-0000-0000-000000000002')$$,'42501',null,'explicit foreign organization is denied');
select is((select count(*) from public.normalize_procurement_import_refs(array['  İΣς ','  İΣς  ','other'])),3::bigint,'normalization returns every source reference');
select is((select normalized_ref from public.normalize_procurement_import_refs(array['  İΣς '])) ,lower(btrim('  İΣς ')),'Unicode normalization follows PostgreSQL');
reset role;
set local role service_role;
set local request.jwt.claims = '{"role":"service_role"}';
select is((select count(*) from public.lookup_procurement_import_cases(array['alpha'],p_org_id=>'39940000-0000-0000-0000-000000000002')),1::bigint,'trusted lookup scopes to explicit organization');
select throws_ok($$select * from public.lookup_procurement_import_cases(array['alpha'])$$,'42501',null,'trusted lookup requires explicit organization');
select * from finish();
rollback;
